    "Visor de edición Qwen-Image 2.1 Uncensored. Dibuja máscara de inpainting o edita con hasta 10 imágenes de referencia. Requiere los 3 archivos de Qwen-Image 2.1 Uncensored en ComfyUI/models (diffusion_models, text_encoders, vae) y el nodo ComfyUI-GGUF actualizado.": "Qwen-Image 2.1 Uncensored editing viewer. Draw an inpainting mask or edit with up to 10 reference images. Requires the 3 Qwen-Image 2.1 Uncensored files in ComfyUI/models (diffusion_models, text_encoders, vae) and the updated ComfyUI-GGUF node.",
