    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado": "WaifuStudio manages VRAM with single-threaded FIFO inference. To avoid saturating the 12 GB: 1. In the H3 Video tab, always keep enabled",
    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado VDN 8 pasos y resolución 768p. 2. Evita generar vídeos de más de 10 segundos en una sola pasada; en su lugar, genera clips de 5s y únelos en la pestaña Estudio Timeline con el botón \"Continuar I2V\". 3. El modelo de subtitulado Qwen 2.5 opera en CPU, liberando el 100% de la GPU para renderizado.": "WaifuStudio manages VRAM with single-threaded FIFO inference. To avoid saturating the 12 GB: 1. In the H3 Video tab, always keep VDN 8 steps and 768p resolution enabled. 2. Avoid generating videos longer than 10 seconds in a single pass; instead, generate 5s clips and join them in the Studio Timeline tab with the button \"Continue I2V\". 3. The Qwen 2.5 captioning model runs on CPU, freeing 100% of the GPU for rendering.",
