    ": Ajustes microscópicos de postura y mirada.": ": 姿勢と視線の微調整。",
    ": Al hacer clic en": ": 任意のクリップで",
    ": Aplica nitidez contrastada adaptativa sin generar halos blancos desagradables.": ": 不快な白いハローを生じさせず、適応的なコントラスト強調を適用します。",
    ": Añade clips de tu galería o genera directamente con IA. Cada clip cuenta con control de duración, selector de transiciones (Fade, Zoom In, Zoom Out) y botón de silenciar (": ": ギャラリーからクリップを追加するか、AIで直接生成します。各クリップには長さの調整、トランジションの選択 (Fade, Zoom In, Zoom Out)、ミュートボタン (",
    ": El botón": ": ボタン",
    ": Emplea el sampler": ": samplerを使い、",
    ": Giros de cabeza y cambios suaves de extremidades.": ": 頭の向きの変化と四肢の滑らかな動き。",
    ": Guarda a tu personaje con nombre, rasgos fijos e imágenes de referencia. Desde el modal de OC Maker puedes generar automáticamente una": ": キャラクターを名前、固定の特徴、参照画像とともに保存します。OC Makerのモーダルでは、",
    ": Modelos": ": モデル",
    ": Motor clásico para estilos artísticos densos e ilustraciones complejas. Detecta automáticamente la arquitectura de tensores al cargar LoRAs.": ": 濃密な画風や複雑なイラスト向けの定番エンジン。LoRAの読み込み時にテンソルアーキテクチャを自動検出します。",
    ": Motor nativo optimizado para RTX 3060. Extremadamente rápido (~3-5 s por imagen), responde con gran precisión a tags Danbooru (ej.": ": RTX 3060向けに最適化されたネイティブエンジン。非常に高速 (1枚あたり約3〜5秒) であり、Danbooruタグ (例:",
    ": Multiplica los fotogramas de tus vídeos a ×2 o ×4 fps conservando el audio intacto para máxima fluidez anime.": ": 動画のフレームレートを×2または×4 fpsに増やし、音声をそのまま保ってアニメの動きを最大限に滑らかにします。",
    ": Pinta con el pincel sobre cualquier área de la imagen para cambiar ropa, alterar expresiones faciales o corregir detalles anatómicos sin tocar el resto de la ilustración.": ": 画像の任意の領域をブラシで塗り、イラストの他の部分に触れずに、服装の変更、表情の調整、解剖学的なディテールの修正を行います。",
    ": Poses dinámicas de cuerpo entero.": ": 全身のダイナミックなポーズ。",
    ": Puedes estructurar tu prompt dividiéndolo en bloques modulares (": ": promptをモジュール式のブロック (",
    ": Reconfiguración anatómica radical y ángulos complejos.": ": 抜本的な解剖学的再構成と複雑なアングル。",
    ": Reconstrucción ultra-detallada a 2048px preservando el estilo original.": ": 元のスタイルを保ちながら2048pxで超高精細に再構築します。",
    ": Redibuja micro-detalles reales (pestañas individuales, brillo en el iris, hebras de cabello) con un denoise recomendado de": ": まつげの一本一本、虹彩の輝き、髪の毛の繊維といった微細なディテールを、推奨されるdenoise値は",
    ": Reduce el tiempo de cálculo de ~6 minutos a solo ~60 segundos manteniendo nitidez impecable. Mantén el botón VDN siempre activo en configuraciones de 12 GB.": ": 計算時間を約6分からわずか約60秒に短縮し、鮮明さを損ないません。12GB構成ではVDNボタンを常に有効にしてください。",
    ": Sube archivos de audio (.mp3, .wav), colócalos en el segundo exacto que desees y gradúa su volumen para añadir bandas sonoras y efectos.": ": 音声ファイル (.mp3, .wav) をアップロードし、指定した秒に正確に配置して音量を調整すると、サウンドトラックや効果音を追加できます。",
    "A más resolución de entrada, más detalle facial. Para vertical usa 9:16 (~1008×1792); para horizontal 16:9 (~1792×1008).": "入力解像度が高いほど、顔のディテールが向上します。縦は9:16 (約1008×1792)、横は16:9 (約1792×1008) を使用してください。",
    "A más resolución de entrada, más detalle facial. Para vertical usa 9:16 (~1008×1792); para horizontal 16:9 (~1792×1008). Referencias se recortan centradas si difiere el ratio.": "入力解像度が高いほど、顔のディテールが向上します。縦は9:16 (約1008×1792)、横は16:9 (約1792×1008) を使用してください。アスペクト比が異なる場合、参照画像は中央でトリミングされます。",
