    "Continuar I2V (Secuencias Infinitas)": "I2Vを続行 (無限シーケンス)",
    "Continuar I2V (Secuencias Infinitas): Al hacer clic en \"⏭️ I2V\" en cualquier clip, la app extrae automáticamente su último fotograma y lo anima con la acción descrita, encadenando escenas sucesivas sin límite de tiempo.": "I2Vを続行 (無限シーケンス): 任意のクリップで\"⏭️ I2V\"をクリックすると、アプリは最後のフレームを自動的に抽出し、記述された動作でアニメーション化して、後続のシーンを時間制限なく連結します。",
