    "Cámara y Tomas: close-up shot (primer plano), medium shot (plano medio), full body shot (entero), low angle shot (contrapicado), slow pan right/left (paneo), slow dolly in (acercamiento suave), subtle handheld camera movement. Mantener una sola toma continua: sin cortes.": "カメラとショット: close-up shot (クローズアップ), medium shot (ミディアムショット), full body shot (全身), low angle shot (ローアングル), slow pan right/left (パン), slow dolly in (緩やかなドリーイン), subtle handheld camera movement. カットを入れず、1つの連続ショットを維持します。",
