    "Descargar": "ダウンロード",
    "Describe en lenguaje natural qué generar o modificar en la imagen con Qwen-Image 2.1.": "Qwen-Image 2.1で画像に何を生成・変更するかを自然言語で記述してください。",
    "Describe en lenguaje natural: escena, personaje, acción, estilo…": "自然言語で記述: シーン、キャラクター、アクション、スタイル…",
