    "Describe la acción en presente (ej.": "動作は現在形で記述します (例:",
    "Describe la acción en presente (ej. \"waves hair, smiles softly, turns head\").": "動作は現在形で記述します (例: \"waves hair, smiles softly, turns head\")。",
    "Describe la escena en lenguaje natural: sujeto, estilo, entorno o acción. Se descompone automáticamente en tags danbooru por zonas.": "シーンを自然言語で記述: 被写体、スタイル、環境、アクション。ゾーンごとにdanbooru tagsへ自動分解されます。",
