    "Dimensiones Resultantes": "結果のサイズ",
    "Diseña tu waifu con Anima 2.9B o SDXL, guarda su identidad en OC Maker y genera su hoja de vistas.": "Anima 2.9BまたはSDXLでwaifuをデザインし、OC Makerにその同一性を保存して、キャラクターシートを生成します。",
    "Diálogo:": "セリフ:",
    "Diálogo: Con idioma explícito <d>[Español] texto</d> y un speaker id estable antes de las voces (ej. speaker_1); no llenar más de ~2/3 de su plano.": "セリフ: 言語を明示した <d>[Español] texto</d> と、音声の前に安定したspeaker id (例: speaker_1) を指定します。画面の約2/3以上は埋めないでください。",
    "Duplica los fotogramas (2x fps) durante el escalado de vídeo.": "動画のスケーリング中にフレームを2倍 (2x fps) にします。",
