    "El Editor integra el modelo de visión y difusión Qwen 2.1 para edición quirúrgica:": "エディタには、視覚・拡散モデル Qwen 2.1 が統合されており、精密な編集を行えます:",
    "El clip de referencia no tiene configuración guardada; vuelve a añadirlo desde la Biblioteca.": "参照クリップに保存された設定がありません。ライブラリから追加し直してください。",
    "El dataset debe ser de 10-50 imágenes coherentes del mismo OC.": "データセットは同じOCの一貫した画像を10〜50枚にしてください。",
    "El modelo no devolvió tags ni caption.": "モデルからtagsもキャプションも返されませんでした。",
    "El motor de escalado eleva tus creaciones a resolución 2K y 60 FPS:": "スケーリングエンジンは、作品を2K解像度と60 FPSに引き上げます:",
    "El motor de vídeo de WaifuStudio utiliza": "WaifuStudioの動画エンジンは、",
    "El motor de vídeo de WaifuStudio utiliza H3 (Wan 2.1) potenciado con VideoDeltaNet (VDN) en 8 pasos, permitiendo generar animaciones fluidas en GPU de 12 GB VRAM en tiempo récord.": "WaifuStudioの動画エンジンは、H3 (Wan 2.1) をベースに、VideoDeltaNet (VDN) を8ステップで使用し、12GB VRAMのGPUで流れるようなアニメーションを短時間で生成できます。",
    "El nombre es obligatorio": "名前は必須です",
    "El prompt no puede estar vacío": "promptが空です",
    "El servidor no devolvió un estado válido del job; revisa la Galería o reinicia la app.": "サーバーから有効なジョブ状態が返されませんでした。ギャラリーを確認するか、アプリを再起動してください。",
    "Elegir LoRAs (0)": "LoRAを選択 (0)",
    "Elige el modelo Anima base, preprompt de estilo, clasificación de contenido y LoRAs instaladas.": "Animaベースモデル、スタイルpreprompt、コンテンツ分類、インストール済みLoRAを選択します。",
    "Elige si escalar imagen, vídeo o interpolar fotogramas (FPS). Selecciona una generación de la galería o un archivo local.": "画像のスケーリング、動画のスケーリング、フレーム補間 (FPS) のどれを行うかを選択します。ギャラリーの生成結果またはローカルファイルを選択してください。",
    "Elige un OC en «Mis OCs» o añade el tag a mano. / Sin opciones.": "「マイOCs」でOCを選択するか、tagを手動で追加してください。 / オプションなし。",
    "Elige un OC o escribe un nombre nuevo": "OCを選択するか、新しい名前を入力してください",
    "Elige un OC o escribe un nombre.": "OCを選択するか、名前を入力してください。",
