    "Elige un ckpt RIFE": "RIFE ckptを選択してください",
    "Elige un modelo de escalado": "拡大モデルを選択してください",
    "Elige una imagen de tu disco y añade su descripción (tags + caption) al prompt, igual que «Describir» en la galería.": "ディスクから画像を選び、その説明 (tags + caption) をpromptに追加します。ギャラリーの「説明」と同じ動作です。",
    "Elige una miniatura de la galería o genera un vídeo en la pestaña Vídeo": "ギャラリーのサムネイルを選択するか、「動画」タブで動画を生成してください",
    "Elige una miniatura de la galería o, en imagen, un archivo local (el archivo sustituye a la selección).": "ギャラリーのサムネイル、または画像の場合はローカルファイルを選択します (ファイルは選択内容を置き換えます)。",
    "Elige una miniatura o un archivo local": "サムネイルまたはローカルファイルを選択してください",
    "Eliminar": "削除",
    "En cola / Generando": "キュー待ち / 生成中",
    "En los modelos I2V basados en Wan 2.1 / H3, el movimiento proviene del prompt: 1. Usa verbos dinámicos en inglés:": "Wan 2.1 / H3ベースのI2Vモデルでは、動きはpromptから生まれます。1. 英語の動作動詞を使って記述します:",
    "En los modelos I2V basados en Wan 2.1 / H3, el movimiento proviene del prompt: 1. Usa verbos dinámicos en inglés: \"running towards camera, intense action, wind blowing hair strongly, dramatic expression\". 2. En el panel de Vídeo, puedes usar el selector de presets H3 para aplicar movimientos de cámara como Zoom In, Pan Left, Tilt Up o Dynamic Action.": "Wan 2.1 / H3ベースのI2Vモデルでは、動きはpromptから生まれます。1. 英語の動作動詞を使って記述します: \"running towards camera, intense action, wind blowing hair strongly, dramatic expression\"。2. 動画パネルでは、H3プリセットセレクターを使って、次のようなカメラワークを適用できます: Zoom In、Pan Left、Tilt Up、Dynamic Action。",
    "En «Editar» se trabaja sobre la imagen seleccionada en el visor de Imagen (o clic en la galería de abajo); describe el cambio.": "「編集」では、画像ビューアで選択した画像 (または下のギャラリーをクリック) を対象に、変更内容を記述します。",
    "En «Editar» se trabaja sobre la imagen seleccionada en el visor o galería. En «Generar» guían hasta 10 referencias de estilo/composición.": "「編集」ではビューアまたはギャラリーで選択した画像を対象に作業します。「生成」では最大10枚の参照がスタイル/構図を誘導します。",
