    "H3 espera tres bloques en inglés técnico, en una sola toma continua por generación (sin cortes, también aplica a FL2VA):": "H3は、技術的な英語による3つのブロックを、1回の生成につき1つの連続ショットで受け付けます (カットなし、FL2VAにも適用):",
    "H3 espera tres bloques en inglés técnico: multimodal, paisaje sonoro foley y música instrumental.": "H3は技術的な英語で3つのブロックを期待します: multimodal、フォーリーのサウンドスケープ、インストゥルメンタル音楽。",
