    "WaifuStudio combina dos familias de modelos para generación de imagen fija:": "WaifuStudioは、静止画像の生成に2つのモデルファミリーを組み合わせます:",
    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado": "WaifuStudioはFIFOによる単一スレッド推論でVRAMを管理します。12GBのVRAMを使い切らないために、1. H3動画では常に",
    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado VDN 8 pasos y resolución 768p. 2. Evita generar vídeos de más de 10 segundos en una sola pasada; en su lugar, genera clips de 5s y únelos en la pestaña Estudio Timeline con el botón \"Continuar I2V\". 3. El modelo de subtitulado Qwen 2.5 opera en CPU, liberando el 100% de la GPU para renderizado.": "WaifuStudioはFIFOによる単一スレッド推論でVRAMを管理します。12GBのVRAMを使い切らないために、1. H3動画では常にVDN 8ステップと解像度768pを有効にします。2. 10秒を超える動画を1回で生成するのは避け、代わりに5秒のクリップを生成して「Timelineスタジオ」タブの「I2Vを続行」ボタンで連結します。3. 字幕モデルのQwen 2.5はCPUで動作し、GPUを100%レンダリングに使用できます。",
