    "● Laboratorio listo": "● ラボ準備完了",
    "⚠️ En GPUs de 12GB (como RTX 3060), esta resolución puede requerir >16GB VRAM y generar error Out Of Memory (OOM). Si ocurre, usa HD o reduce la duración.": "⚠️ 12GBのGPU (RTX 3060など) では、この解像度に16GB超のVRAMが必要になり、Out Of Memory (OOM) エラーが発生する可能性があります。その場合はHDを使用するか、再生時間を短くしてください。",
    "⚠️ Qwen3-VL 32B consume >16 GB VRAM y forzará swap a RAM en la RTX 3060 (mayor tiempo de render).": "⚠️ Qwen3-VL 32Bは16GB超のVRAMを消費し、RTX 3060ではRAMへのスワップが発生します (レンダリング時間が増加)。",
