    ": Ajustes microscópicos de postura y mirada.": ": Микронастройки позы и взгляда.",
    ": Al hacer clic en": ": при нажатии на",
    ": Aplica nitidez contrastada adaptativa sin generar halos blancos desagradables.": ": применяет адаптивную контрастную резкость без неприятных белых ореолов.",
    ": Añade clips de tu galería o genera directamente con IA. Cada clip cuenta con control de duración, selector de transiciones (Fade, Zoom In, Zoom Out) y botón de silenciar (": ": добавлять клипы из галереи или генерировать напрямую с помощью ИИ. Для каждого клипа доступны управление длительностью, выбор переходов (Fade, Zoom In, Zoom Out) и кнопка отключения звука (",
    ": El botón": ": кнопка",
    ": Emplea el sampler": ": использовать сэмплер",
    ": Giros de cabeza y cambios suaves de extremidades.": ": Повороты головы и плавные изменения конечностей.",
    ": Guarda a tu personaje con nombre, rasgos fijos e imágenes de referencia. Desde el modal de OC Maker puedes generar automáticamente una": ": сохранить персонажа с именем, фиксированными чертами и референс-изображениями. В модальном окне OC Maker можно автоматически создать",
    ": Modelos": ": модели",
    ": Motor clásico para estilos artísticos densos e ilustraciones complejas. Detecta automáticamente la arquitectura de tensores al cargar LoRAs.": ": классический движок для насыщенных художественных стилей и сложных иллюстраций. Автоматически определяет архитектуру тензоров при загрузке LoRA.",
    ": Motor nativo optimizado para RTX 3060. Extremadamente rápido (~3-5 s por imagen), responde con gran precisión a tags Danbooru (ej.": ": нативный движок, оптимизированный для RTX 3060. Чрезвычайно быстрый (~3-5 с на изображение), с высокой точностью реагирует на теги Danbooru (например,",
    ": Multiplica los fotogramas de tus vídeos a ×2 o ×4 fps conservando el audio intacto para máxima fluidez anime.": ": умножает частоту кадров видео на ×2 или ×4, сохраняя звук без изменений для максимальной плавности аниме.",
    ": Pinta con el pincel sobre cualquier área de la imagen para cambiar ropa, alterar expresiones faciales o corregir detalles anatómicos sin tocar el resto de la ilustración.": ": рисовать кистью по любой области изображения, чтобы изменить одежду, выражение лица или исправить анатомические детали, не затрагивая остальную иллюстрацию.",
    ": Poses dinámicas de cuerpo entero.": ": Динамичные позы в полный рост.",
    ": Puedes estructurar tu prompt dividiéndolo en bloques modulares (": ": можно структурировать промпт, разделив его на модульные блоки (",
    ": Reconfiguración anatómica radical y ángulos complejos.": ": Радикальная перестройка анатомии и сложные ракурсы.",
    ": Reconstrucción ultra-detallada a 2048px preservando el estilo original.": ": сверхдетальная реконструкция до 2048px с сохранением исходного стиля.",
    ": Redibuja micro-detalles reales (pestañas individuales, brillo en el iris, hebras de cabello) con un denoise recomendado de": ": перерисовывает реальные микродетали (отдельные ресницы, блик в радужке, пряди волос) при рекомендуемом значении denoise",
    ": Reduce el tiempo de cálculo de ~6 minutos a solo ~60 segundos manteniendo nitidez impecable. Mantén el botón VDN siempre activo en configuraciones de 12 GB.": ": сокращает время расчёта с ~6 минут до ~60 секунд, сохраняя безупречную резкость. Держать кнопку VDN всегда включённой в конфигурациях с 12 ГБ.",
    ": Sube archivos de audio (.mp3, .wav), colócalos en el segundo exacto que desees y gradúa su volumen para añadir bandas sonoras y efectos.": ": загружать аудиофайлы (.mp3, .wav), размещать их на нужной секунде и регулировать громкость, чтобы добавлять саундтреки и эффекты.",
    "A más resolución de entrada, más detalle facial. Para vertical usa 9:16 (~1008×1792); para horizontal 16:9 (~1792×1008).": "Чем выше разрешение входного изображения, тем больше деталей лица. Для вертикали используйте 9:16 (~1008×1792), для горизонтали — 16:9 (~1792×1008).",
    "A más resolución de entrada, más detalle facial. Para vertical usa 9:16 (~1008×1792); para horizontal 16:9 (~1792×1008). Referencias se recortan centradas si difiere el ratio.": "Чем выше разрешение входного изображения, тем больше деталей лица. Для вертикали используйте 9:16 (~1008×1792), для горизонтали — 16:9 (~1792×1008). Референсы обрезаются по центру при другом соотношении сторон.",
