    "Cámara y Tomas: close-up shot (primer plano), medium shot (plano medio), full body shot (entero), low angle shot (contrapicado), slow pan right/left (paneo), slow dolly in (acercamiento suave), subtle handheld camera movement. Mantener una sola toma continua: sin cortes.": "Камера и планы: close-up shot (крупный план), medium shot (средний план), full body shot (в полный рост), low angle shot (нижний ракурс), slow pan right/left (панорамирование), slow dolly in (плавный наезд), subtle handheld camera movement. Сохранять один непрерывный план: без склеек.",
