    "Describe la acción (ej: el personaje empieza a correr y salta un obstáculo)...": "Опишите действие (например, персонаж начинает бежать и перепрыгивает препятствие)...",
    "Describe la acción en presente (ej.": "Описывать действие в настоящем времени (например,",
    "Describe la acción en presente (ej. \"waves hair, smiles softly, turns head\").": "Описывать действие в настоящем времени (например, \"waves hair, smiles softly, turns head\").",
    "Describe la escena en lenguaje natural: sujeto, estilo, entorno o acción. Se descompone automáticamente en tags danbooru por zonas.": "Опишите сцену естественным языком: субъект, стиль, окружение или действие. Она автоматически разбивается на теги danbooru по зонам.",
    "Describe qué generar o editar...": "Опишите, что создать или отредактировать...",
