    "Diseña tu waifu con Anima 2.9B o SDXL, guarda su identidad en OC Maker y genera su hoja de vistas.": "Создать вайфу с Anima 2.9B или SDXL, сохранить её идентичность в OC Maker и сгенерировать лист с видами.",
    "Diálogo:": "Диалог:",
    "Diálogo: Con idioma explícito <d>[Español] texto</d> y un speaker id estable antes de las voces (ej. speaker_1); no llenar más de ~2/3 de su plano.": "Диалог: с указанием языка, например <d>[Español] texto</d>, и стабильным speaker id перед голосами (например, speaker_1); не заполнять более ~2/3 кадра.",
