    "Editar necesita una imagen: selecciónala en el visor de Imagen o en la galería": "«Редактировать» требует изображение: выберите его в просмотрщике «Изображение» или в галерее",
    "Editar usa la imagen seleccionada en el visor de Imagen": "«Редактировать» использует изображение, выбранное в просмотрщике «Изображение»",
