    "Editor (Qwen-Image 2.1)": "Редактор (Qwen-Image 2.1)",
    "El Editor integra el modelo de visión y difusión": "Редактор использует модель зрения и диффузии",
    "El Editor integra el modelo de visión y difusión Qwen 2.1 para edición quirúrgica:": "Редактор использует модель зрения и диффузии Qwen 2.1 для точечного редактирования:",
    "El clip de referencia no tiene configuración guardada; vuelve a añadirlo desde la Biblioteca.": "У референс-клипа нет сохранённых настроек; добавьте его снова из медиатеки.",
    "El dataset debe ser de 10-50 imágenes coherentes del mismo OC.": "Датасет должен состоять из 10-50 согласованных изображений одного OC.",
    "El modelo no devolvió tags ni caption.": "Модель не вернула ни теги, ни caption.",
    "El motor de escalado eleva tus creaciones a resolución 2K y 60 FPS:": "Движок увеличения повышает разрешение ваших работ до 2K и 60 FPS:",
    "El motor de vídeo de WaifuStudio utiliza": "Видеодвижок WaifuStudio использует",
    "El motor de vídeo de WaifuStudio utiliza H3 (Wan 2.1) potenciado con VideoDeltaNet (VDN) en 8 pasos, permitiendo generar animaciones fluidas en GPU de 12 GB VRAM en tiempo récord.": "Видеодвижок WaifuStudio использует H3 (Wan 2.1) в паре с VideoDeltaNet (VDN) за 8 шагов, что позволяет создавать плавные анимации на GPU с 12 ГБ VRAM в рекордно короткие сроки.",
    "El nombre es obligatorio": "Имя обязательно",
    "El prompt no puede estar vacío": "Промпт не может быть пустым",
    "El servidor no devolvió un estado válido del job; revisa la Galería o reinicia la app.": "Сервер не вернул корректное состояние задачи; проверьте галерею или перезапустите приложение.",
    "Elegir LoRAs (0)": "Выбрать LoRA (0)",
    "Elige el modelo Anima base, preprompt de estilo, clasificación de contenido y LoRAs instaladas.": "Выберите базовую модель Anima, пресет стиля, классификацию контента и установленные LoRA.",
    "Elige si escalar imagen, vídeo o interpolar fotogramas (FPS). Selecciona una generación de la galería o un archivo local.": "Выберите, что делать: увеличить изображение, видео или интерполировать кадры (FPS). Выберите генерацию из галереи или локальный файл.",
    "Elige un OC en «Mis OCs» o añade el tag a mano. / Sin opciones.": "Выберите OC в «Мои OC» или добавьте тег вручную. / Нет вариантов.",
    "Elige un OC o escribe un nombre nuevo": "Выберите OC или введите новое имя",
    "Elige un OC o escribe un nombre.": "Выберите OC или введите имя.",
    "Elige un archivo .safetensors para cargar": "Выберите файл .safetensors для загрузки",
    "Elige un ckpt RIFE": "Выберите ckpt RIFE",
    "Elige un modelo de escalado": "Выберите модель увеличения",
    "Elige una imagen de tu disco y añade su descripción (tags + caption) al prompt, igual que «Describir» en la galería.": "Выберите изображение на диске и добавьте его описание (теги + caption) в промпт — так же, как «Описать» в галерее.",
    "Elige una miniatura de la galería o genera un vídeo en la pestaña Vídeo": "Выберите миниатюру из галереи или создайте видео на вкладке «Видео»",
    "Elige una miniatura de la galería o, en imagen, un archivo local (el archivo sustituye a la selección).": "Выберите миниатюру из галереи или, для изображения, локальный файл (файл заменяет выбранное).",
    "Elige una miniatura o un archivo local": "Выберите миниатюру или локальный файл",
    "Eliminar": "Удалить",
    "En cola / Generando": "В очереди / Генерация",
    "En los modelos I2V basados en Wan 2.1 / H3, el movimiento proviene del prompt: 1. Usa verbos dinámicos en inglés:": "В моделях I2V на основе Wan 2.1 / H3 движение задаётся промптом: 1. Использовать динамичные глаголы на английском:",
    "En los modelos I2V basados en Wan 2.1 / H3, el movimiento proviene del prompt: 1. Usa verbos dinámicos en inglés: \"running towards camera, intense action, wind blowing hair strongly, dramatic expression\". 2. En el panel de Vídeo, puedes usar el selector de presets H3 para aplicar movimientos de cámara como Zoom In, Pan Left, Tilt Up o Dynamic Action.": "В моделях I2V на основе Wan 2.1 / H3 движение задаётся промптом: 1. Использовать динамичные глаголы на английском: \"running towards camera, intense action, wind blowing hair strongly, dramatic expression\". 2. На панели Видео можно использовать селектор пресетов H3, чтобы применять движения камеры, например Zoom In, Pan Left, Tilt Up или Dynamic Action.",
    "En «Editar» se trabaja sobre la imagen seleccionada en el visor de Imagen (o clic en la galería de abajo); describe el cambio.": "В режиме «Редактировать» работа идёт с изображением, выбранным в просмотрщике вкладки «Изображение» (или по клику в галерее ниже); опишите изменение.",
    "En «Editar» se trabaja sobre la imagen seleccionada en el visor o galería. En «Generar» guían hasta 10 referencias de estilo/composición.": "В режиме «Редактировать» работа идёт с изображением, выбранным в просмотрщике или галерее. В режиме «Создать» стиль/композицию задают до 10 референсов.",
    "Encolando animación I2V...": "Постановка анимации I2V в очередь...",
