    "Video Delta Net (VDN) 8 pasos + Text Encoder 4B; balance perfecto calidad/VRAM para RTX 3060": "Video Delta Net (VDN), 8 шагов + Text Encoder 4B; баланс качества и VRAM для RTX 3060",
