    "VideoDeltaNet (8 pasos)": "VideoDeltaNet (8 шагов)",
    "VideoDeltaNet (8 pasos): Reduce el tiempo de cálculo de ~6 minutos a solo ~60 segundos manteniendo nitidez impecable. Mantén el botón VDN siempre activo en configuraciones de 12 GB.": "VideoDeltaNet (8 шагов): сокращает время расчёта с ~6 минут до ~60 секунд, сохраняя безупречную резкость. Держать кнопку VDN всегда включённой в конфигурациях с 12 ГБ.",
    "Visor de edición Qwen-Image 2.1 Uncensored. Dibuja máscara de inpainting o edita con hasta 10 imágenes de referencia. Requiere los 3 archivos de Qwen-Image 2.1 Uncensored en ComfyUI/models (diffusion_models, text_encoders, vae) y el nodo ComfyUI-GGUF actualizado.": "Просмотрщик редактирования Qwen-Image 2.1 Uncensored. Нарисуйте маску инпейнтинга или редактируйте с помощью до 10 референс-изображений. Требует 3 файла Qwen-Image 2.1 Uncensored в ComfyUI/models (diffusion_models, text_encoders, vae) и обновлённый узел ComfyUI-GGUF.",
    "Vídeo": "Видео",
    "Vídeo de origen / Imagen de origen": "Исходное видео / Исходное изображение",
    "Vídeos": "Видео",
    "WAIFU": "WAIFU",
    "WD14 no instalado: se usarán solo los tags del OC.": "WD14 не установлен: будут использоваться только теги OC.",
    "WaifuStudio combina dos familias de modelos para generación de imagen fija:": "WaifuStudio объединяет два семейства моделей для генерации изображений:",
    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado": "WaifuStudio управляет VRAM с помощью однопоточной FIFO-инференции. Чтобы не перегружать 12 ГБ VRAM: 1. В разделе Видео H3 всегда держать включённым режим",
    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado VDN 8 pasos y resolución 768p. 2. Evita generar vídeos de más de 10 segundos en una sola pasada; en su lugar, genera clips de 5s y únelos en la pestaña Estudio Timeline con el botón \"Continuar I2V\". 3. El modelo de subtitulado Qwen 2.5 opera en CPU, liberando el 100% de la GPU para renderizado.": "WaifuStudio управляет VRAM с помощью однопоточной FIFO-инференции. Чтобы не перегружать 12 ГБ VRAM: 1. В разделе Видео H3 всегда держать включённым режим VDN 8 шагов и разрешение 768p. 2. Не генерировать видео длиннее 10 секунд за один проход; вместо этого создавать клипы по 5 с и объединять их на вкладке Студия Timeline с помощью кнопки \"Продолжить I2V\". 3. Модель субтитров Qwen 2.5 работает на CPU, освобождая 100% GPU для рендеринга.",
    "Zona": "Зона",
    "Zonas de Prompt": "Зоны промпта",
    "Zonas de Prompt: Puedes estructurar tu prompt dividiéndolo en bloques modulares (Sujeto, Atuendo, Entorno/Fondo, NSFW y Acción) para evitar que los tags se contaminen entre sí.": "Зоны промпта: можно структурировать промпт, разделив его на модульные блоки (Субъект, одежда, окружение/фон, NSFW и действие), чтобы теги не смешивались друг с другом.",
    "Zoom In, Pan Left, Tilt Up o Dynamic Action": "Zoom In, Pan Left, Tilt Up или Dynamic Action",
