    "dpmpp_2m": "dpmpp_2m",
    "en 8 pasos, permitiendo generar animaciones fluidas en GPU de 12 GB VRAM en tiempo récord.": "за 8 шагов, что позволяет создавать плавные анимации на GPU с 12 ГБ VRAM в рекордно короткие сроки.",
