    ": Ajustes microscópicos de postura y mirada.": ": 姿势与视线的细微调整。",
    ": Al hacer clic en": ": 点击任意片段上的",
    ": Aplica nitidez contrastada adaptativa sin generar halos blancos desagradables.": ": 应用自适应对比锐化，不产生难看的白色光晕。",
    ": Añade clips de tu galería o genera directamente con IA. Cada clip cuenta con control de duración, selector de transiciones (Fade, Zoom In, Zoom Out) y botón de silenciar (": ": 从图库添加片段，或直接用 AI 生成。每个片段都有时长控制、转场选择器 (Fade、Zoom In、Zoom Out) 和静音按钮 (",
    ": El botón": ": 点击",
    ": Emplea el sampler": ": 使用采样器",
    ": Giros de cabeza y cambios suaves de extremidades.": ": 头部转动与肢体轻微变化。",
    ": Guarda a tu personaje con nombre, rasgos fijos e imágenes de referencia. Desde el modal de OC Maker puedes generar automáticamente una": ": 为角色保存名称、固定特征和参考图。在 OC Maker 弹窗中，你可以自动生成一张",
    ": Modelos": ": 模型",
    ": Motor clásico para estilos artísticos densos e ilustraciones complejas. Detecta automáticamente la arquitectura de tensores al cargar LoRAs.": ": 经典引擎，适合厚重艺术风格与复杂插画。加载 LoRA 时会自动识别张量架构。",
    ": Motor nativo optimizado para RTX 3060. Extremadamente rápido (~3-5 s por imagen), responde con gran precisión a tags Danbooru (ej.": ": 针对 RTX 3060 优化的原生引擎。速度极快 (每张约 3-5 s)，能精准响应 Danbooru 标签 (例如",
    ": Multiplica los fotogramas de tus vídeos a ×2 o ×4 fps conservando el audio intacto para máxima fluidez anime.": ": 将视频帧率提升至 ×2 或 ×4 fps，音频保持不变，获得最流畅的动画效果。",
    ": Pinta con el pincel sobre cualquier área de la imagen para cambiar ropa, alterar expresiones faciales o corregir detalles anatómicos sin tocar el resto de la ilustración.": ": 用画笔涂抹图像任意区域，可更换服装、修改面部表情或修正解剖细节，不影响画面其余部分。",
    ": Poses dinámicas de cuerpo entero.": ": 全身动态姿势。",
    ": Puedes estructurar tu prompt dividiéndolo en bloques modulares (": ": 你可以把 prompt 拆分为模块化区块 (",
    ": Reconfiguración anatómica radical y ángulos complejos.": ": 大幅改变人体结构与复杂视角。",
    ": Reconstrucción ultra-detallada a 2048px preservando el estilo original.": ": 2048px 超细节重建，保留原有风格。",
    ": Redibuja micro-detalles reales (pestañas individuales, brillo en el iris, hebras de cabello) con un denoise recomendado de": ": 重绘真实的微细节 (单根睫毛、虹膜高光、发丝)，推荐 denoise 为",
    ": Reduce el tiempo de cálculo de ~6 minutos a solo ~60 segundos manteniendo nitidez impecable. Mantén el botón VDN siempre activo en configuraciones de 12 GB.": ": 将计算时间从约 6 分钟缩短到约 60 秒，同时保持锐利度。在 12 GB 显存配置下请保持 VDN 按钮常开。",
    ": Sube archivos de audio (.mp3, .wav), colócalos en el segundo exacto que desees y gradúa su volumen para añadir bandas sonoras y efectos.": ": 上传音频文件 (.mp3、.wav)，放到所需的精确秒数，并调节音量，以添加配乐和音效。",
    "A más resolución de entrada, más detalle facial. Para vertical usa 9:16 (~1008×1792); para horizontal 16:9 (~1792×1008).": "输入分辨率越高，面部细节越丰富。竖屏请用 9:16 (~1008×1792)；横屏请用 16:9 (~1792×1008)。",
    "A más resolución de entrada, más detalle facial. Para vertical usa 9:16 (~1008×1792); para horizontal 16:9 (~1792×1008). Referencias se recortan centradas si difiere el ratio.": "输入分辨率越高，面部细节越丰富。竖屏请用 9:16 (~1008×1792)；横屏请用 16:9 (~1792×1008)。比例不一致时，参考图会被居中裁剪。",
