    "El motor de vídeo de WaifuStudio utiliza H3 (Wan 2.1) potenciado con VideoDeltaNet (VDN) en 8 pasos, permitiendo generar animaciones fluidas en GPU de 12 GB VRAM en tiempo récord.": "WaifuStudio 的视频引擎采用 H3 (Wan 2.1)，并借助 VideoDeltaNet (VDN)，仅需 8 步，即可在 12 GB 显存的 GPU 上快速生成流畅动画。",
