    "En los modelos I2V basados en Wan 2.1 / H3, el movimiento proviene del prompt: 1. Usa verbos dinámicos en inglés:": "在基于 Wan 2.1 / H3 的 I2V 模型中，运动来自 prompt：1. 使用英文动态动词：",
    "En los modelos I2V basados en Wan 2.1 / H3, el movimiento proviene del prompt: 1. Usa verbos dinámicos en inglés: \"running towards camera, intense action, wind blowing hair strongly, dramatic expression\". 2. En el panel de Vídeo, puedes usar el selector de presets H3 para aplicar movimientos de cámara como Zoom In, Pan Left, Tilt Up o Dynamic Action.": "在基于 Wan 2.1 / H3 的 I2V 模型中，运动来自 prompt：1. 使用英文动态动词：\"running towards camera, intense action, wind blowing hair strongly, dramatic expression\"。2. 在视频面板中，可用 H3 预设选择器应用运镜，例如 Zoom In、Pan Left、Tilt Up 或 Dynamic Action。",
    "En «Editar» se trabaja sobre la imagen seleccionada en el visor de Imagen (o clic en la galería de abajo); describe el cambio.": "在«编辑»模式下，操作对象是图像标签页查看器中选中的图像 (或点击下方图库)；请描述修改内容。",
