    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado": "WaifuStudio 通过单线程 FIFO 推理管理显存。为避免占满 12 GB：1. 在视频 H3 中请始终保持启用",
    "WaifuStudio gestiona la VRAM con inferencia monohilo FIFO. Para no saturar los 12 GB: 1. En Vídeo H3 mantén siempre activado VDN 8 pasos y resolución 768p. 2. Evita generar vídeos de más de 10 segundos en una sola pasada; en su lugar, genera clips de 5s y únelos en la pestaña Estudio Timeline con el botón \"Continuar I2V\". 3. El modelo de subtitulado Qwen 2.5 opera en CPU, liberando el 100% de la GPU para renderizado.": "WaifuStudio 通过单线程 FIFO 推理管理显存。为避免占满 12 GB：1. 在视频 H3 中请始终保持启用 VDN 8 步，并将分辨率设为 768p。2. 避免单次生成超过 10 秒的视频；改为生成 5 秒片段，然后在 Timeline 工作室标签页中，点击\"续接 I2V\"。3. 字幕模型 Qwen 2.5 在 CPU 上运行，把 100% 的 GPU 留给渲染。",
